$(document).ready(function() {
    console.log("[Aurora] Console automation loop loaded successfully.");

    // Direct Extraction: Read the perfect hidden input token value generated by Django
    function getCleanCSRFToken() {
        return $('input[name="csrfmiddlewaretoken"]').val();
    }

    // Setup jQuery AJAX defaults safely to completely eliminate frontend header crashes
    $.ajaxSetup({
        beforeSend: function(xhr, settings) {
            if (!/^http:.*/.test(settings.url) && !/^https:.*/.test(settings.url)) {
                const token = getCleanCSRFToken();
                if (token) {
                    xhr.setRequestHeader("X-CSRFToken", token);
                }
            }
        }
    });

    /**
     * HOOK 1: Blueprint Submission Button (Command Wu)
     * Linked downstream to aurora/api/api_commands.py endpoint
     */
    $(document).off('click', '#submit-blueprint').on('click', '#submit-blueprint', function(e) {
        e.preventDefault();
        const blueprintText = $('#blueprint-input').val().trim();
        console.log("[Aurora] Sending blueprint payload:", blueprintText);
        
        if (!blueprintText) {
            alert("Architectural desk error: Blueprint text field is empty.");
            return;
        }

        const $feed = $('#minion-feed');
        const $inspector = $('#inspector-output');
        const $crucible = $('#code-viewer');
        const $telemetry = $('#telemetry-console');

        $feed.html('<div class="text-warning">[System] Blueprint sent to Wu. Initializing assembly line...</div>');
        $inspector.html('<div class="text-muted font-monospace small">Analyzing downstream code generation output...</div>');
        $crucible.text('# Forge processing in progress...');

        // Clear out old console trace history completely on button press
        if ($telemetry.length) {
            $telemetry.html('<span class="text-info fw-bold">[SYSTEM] Resetting stream deck... Pipeline execution loop initialized...</span>');
        }

        $.ajax({
            url: '/aurora/api/command/',
            method: 'POST',
            data: { 'blueprint': blueprintText },
            dataType: 'json',
            success: function(response) {
                if (response.status === 'success') {
                    $feed.html(`<div class="text-light">[System] Code block successfully compiled by Wu.</div>`);
                    if (response.minion_log) {
                        $feed.append(`<div class="text-muted small mt-1">${response.minion_log}</div>`);
                    }
                    $crucible.text(response.generated_code);
                    $inspector.empty();

                    // FIXED: Clears the text area wrapper completely before introducing lines from the latest command
                    if (response.telemetry_stream && $telemetry.length) {
                        let compiledContent = "";
                        let lines = response.telemetry_stream.split('\n');
                        
                        lines.forEach(function(rawLine) {
                            if (!rawLine.trim()) return;
                            let formattedLine = rawLine;
                            if (rawLine.includes("[ERROR]") || rawLine.includes("[CRITICAL]")) {
                                formattedLine = `<span class="text-danger fw-bold">${rawLine}</span>`;
                            } else if (rawLine.includes("SUCCESS:")) {
                                formattedLine = `<span class="text-success fw-bold">${rawLine}</span>`;
                            } else if (rawLine.includes("[FORGE_ENGINE]")) {
                                formattedLine = `<span class="text-muted">${rawLine}</span>`;
                            }
                            compiledContent += (compiledContent ? "\n" : "") + formattedLine;
                        });
                        
                        // Overwrite inner HTML explicitly to throw away old iterations entirely
                        $telemetry.html(compiledContent);
                        $telemetry.scrollTop($telemetry.prop('scrollHeight'));
                    }

                    const val = response.validation;
                    if (val && val.valid) {
                        $inspector.append('<div class="text-success fw-bold">✔ Syntax Check: Passed Cleanly</div>');
                    } else {
                        $inspector.append('<div class="text-danger fw-bold">❌ Syntax Check: Failed</div>');
                    }

                    if (val && val.errors && val.errors.length > 0) {
                        val.errors.forEach(err => {
                            $inspector.append(`<div class="text-danger small ms-2 mt-1">• ${err}</div>`);
                        });
                    }
                }
            },
            error: function(xhr) {
                let errorMsg = 'Critical pipeline communication error occurred.';
                if (xhr.responseJSON && xhr.responseJSON.error) {
                    errorMsg = xhr.responseJSON.error;
                } else if (xhr.status === 403) {
                    errorMsg = 'Security Error: CSRF token handshaking validation rejected.';
                }
                $feed.html(`<div class="text-danger">[Error] ${errorMsg}</div>`);
                $inspector.html('<div class="text-danger">❌ Validation pipeline halted execution.</div>');
                $crucible.text('# Deployment stream disconnected.');
            }
        });
    });

    $(document).off('click', '#forge-deploy').on('click', '#forge-deploy', function() {
        const codeBlock = $('#code-viewer').text();
        if (!codeBlock || codeBlock.startsWith('#')) return;
        $('#minion-feed').append('<div class="text-info mt-2">[Forge] Committing generated modules to active local staging tree...</div>');
    });
});
// ======================================================================
// END: SYSTEM ASSET REFERENCE INTEGRITY ALIGNMENT (PATCH 1 OF 2)
// ======================================================================

