// START: SYSTEM ASSET REFERENCE INTEGRITY ALIGNMENT
// ======================================================================
$(document).ready(function() {
    console.log("[Aurora] Static asset deployment gate bindings initialized.");
    
    /**
     * HOOK 2: Code Forge & Staging Deployment Trigger Action
     * Dispatches current CODE_CRUCIBLE contents downstream to file manager layers
     */
    $(document).off('click', '#forge-deploy').on('click', '#forge-deploy', function(e) {
        e.preventDefault();
        const codeBlock = $('#code-viewer').text();
        
        if (!codeBlock || codeBlock.startsWith('#') || codeBlock.startsWith('//')) {
            console.log("[Forge] Execution skipped: No active code artifact detected inside Crucible viewport.");
            return;
        }
        
        const $feed = $('#minion-feed');
        if ($feed.length) {
            $feed.append('<div class="text-info mt-2 font-monospace small">[FORGE] Committing generated modules to active local staging tree...</div>');
            $feed.scrollTop($feed.prop('scrollHeight'));
        }
    });
});
